namespace sv_80edec2f8f2240ef85cc6ecb707081a0.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_80edec2f8f2240ef85cc6ecb707081a0.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var stepNum = i + 1;
            var cssClass = GetStepClass(stepIndex);
            <li class="step-item @cssClass">
                @if (IsCompleted(stepIndex))
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-circle">&#10003;</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                        <span class="step-circle">@stepNum</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlySet<int> CompletedSteps { get; set; } = new HashSet<int>();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private bool IsCompleted(int step) => CompletedSteps.Contains(step);

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (IsCompleted(step)) return "completed";
        return "future";
    }
}

@namespace sv_80edec2f8f2240ef85cc6ecb707081a0.Components.Pages.Apply
@using sv_80edec2f8f2240ef85cc6ecb707081a0.Models

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Address" @bind:event="oninput" class="form-control" />
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Data { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";
    private string? ErrorMessage { get; set; }
    private bool IsValidating { get; set; }

    protected override void OnParametersSet()
    {
        if (Data is not null)
        {
            FullName = Data.FullName;
            Email = Data.Email;
            Phone = Data.Phone;
            Address = Data.Address;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email.Trim());
            if (!emailValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@namespace sv_80edec2f8f2240ef85cc6ecb707081a0.Components.Pages.Apply

<fieldset class="work-entry-card">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label>Company *</label>
        <input type="text" value="@Company" @oninput="e => { Company = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @oninput="e => { Title = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")); NotifyChanged(); }" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!); NotifyChanged(); }" class="form-control" disabled="@IsCurrent" />
        </div>

        <div class="form-group form-check">
            <label>
                <input type="checkbox" checked="@IsCurrent" @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if(IsCurrent) EndDate = null; NotifyChanged(); }" />
                Currently employed here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Description" @oninput="e => { Description = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" rows="3"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

@namespace sv_80edec2f8f2240ef85cc6ecb707081a0.Components.Pages.Apply
@using sv_80edec2f8f2240ef85cc6ecb707081a0.Models

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <WorkEntryForm
            Index="index"
            Company="@entry.Company"
            Title="@entry.Title"
            StartDate="@entry.StartDate"
            EndDate="@entry.EndDate"
            IsCurrent="@(entry.EndDate == null && !string.IsNullOrEmpty(entry.Company))"
            Description="@entry.Description"
            CanRemove="@(Entries.Count > 1)"
            OnRemove="() => RemoveEntry(index)"
            OnChanged="data => UpdateEntry(index, data)" />
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public WorkHistory? Data { get; set; }
    [Parameter] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntryModel> Entries { get; set; } = new();
    private string? ErrorMessage { get; set; }

    protected override void OnInitialized()
    {
        if (Data is not null && Data.Entries.Count > 0)
        {
            Entries = Data.Entries.Select(e => new WorkEntryModel
            {
                Company = e.Company,
                Title = e.Title,
                StartDate = e.StartDate,
                EndDate = e.EndDate,
                Description = e.Description
            }).ToList();
        }
        else
        {
            Entries = new List<WorkEntryModel> { new() };
        }
    }

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryData data)
    {
        if (index < Entries.Count)
        {
            Entries[index].Company = data.Company;
            Entries[index].Title = data.Title;
            Entries[index].StartDate = data.StartDate;
            Entries[index].EndDate = data.IsCurrent ? null : data.EndDate;
            Entries[index].Description = data.Description;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        var workEntries = Entries.Select(e =>
            new WorkEntry(e.Company.Trim(), e.Title.Trim(), e.StartDate, e.EndDate, e.Description?.Trim() ?? "")
        ).ToList();

        await OnNext.InvokeAsync(new WorkHistory(workEntries));
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }
}

