{"path": "/tmp/sv-80edec2f8f2240ef85cc6ecb707081a0/Components/Pages/Apply/ReviewStep.razor", "file_text": "@namespace sv_80edec2f8f2240ef85cc6ecb707081a0.Components.Pages.Apply
@using sv_80edec2f8f2240ef85cc6ecb707081a0.Models

<div class="step-content">
    <h2>Review &amp; Submit</h2>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h3>Application Submitted!</h3>
            <p>Your application has been received. Your application ID is <strong>#@ApplicationId</strong>.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl>
                    <dt>Name</dt><dd>@Personal.FullName</dd>
                    <dt>Email</dt><dd>@Personal.Email</dd>
                    <dt>Phone</dt><dd>@Personal.Phone</dd>
                    <dt>Address</dt><dd>@Personal.Address</dd>
                </dl>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @if (Work is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <span>@entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</span>
                        @if (!string.IsNullOrEmpty(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-entry">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        @r.Email | @r.Phone
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }

    private async Task HandleSubmit() => await OnSubmit.InvokeAsync();
}
"}

