@namespace sv_80edec2f8f2240ef85cc6ecb707081a0.Components.Pages.Apply

<fieldset class="reference-card">
    <legend>Reference @(Index + 1)</legend>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Name" @oninput="e => { Name = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Relationship" @oninput="e => { Relationship = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @oninput="e => { Email = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @oninput="e => { Phone = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new ReferenceData(Name, Relationship, Email, Phone));
    }

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);
}

@namespace sv_80edec2f8f2240ef85cc6ecb707081a0.Components.Pages.Apply
@using sv_80edec2f8f2240ef85cc6ecb707081a0.Models

<div class="step-content">
    <h2>References</h2>
    <p>Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var r = References[index];
        <ReferenceForm
            Index="index"
            Name="@r.Name"
            Relationship="@r.Relationship"
            Email="@r.Email"
            Phone="@r.Phone"
            CanRemove="@(References.Count > 2)"
            OnRemove="() => RemoveReference(index)"
            OnChanged="data => UpdateReference(index, data)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? Data { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<ReferenceModel> References { get; set; } = new();
    private string? ErrorMessage { get; set; }

    protected override void OnInitialized()
    {
        if (Data is not null && Data.Count > 0)
        {
            References = Data.Select(r => new ReferenceModel
            {
                Name = r.Name,
                Relationship = r.Relationship,
                Email = r.Email,
                Phone = r.Phone
            }).ToList();
        }
        else
        {
            References = new List<ReferenceModel> { new(), new() };
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        if (index < References.Count)
        {
            References[index].Name = data.Name;
            References[index].Relationship = data.Relationship;
            References[index].Email = data.Email;
            References[index].Phone = data.Phone;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All fields are required for each reference.";
                return;
            }
        }

        var refs = References.Select(r =>
            new Reference(r.Name.Trim(), r.Relationship.Trim(), r.Email.Trim(), r.Phone.Trim())
        ).ToList();

        await OnNext.InvokeAsync(refs);
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

