@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Data="personalInfo" ApplicationService="ApplicationService"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Data="workHistory" OnNext="HandleWorkHistoryNext" OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep Data="references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep Data="coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo" Work="workHistory" References="references"
                        CoverLetter="coverLetter" OnBack="GoBack" OnEditSection="GoToStep"
                        OnSubmit="HandleSubmit" IsSubmitting="isSubmitting"
                        IsSubmitted="isSubmitted" ApplicationId="applicationId"
                        ErrorMessage="submitError" />
            break;
    }
</div>

