    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    private PersonalInfo? personalInfo;
    private WorkHistory? workHistory;
    private List<Reference>? references;
    private string? coverLetter;

    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
            currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfo data)
    {
        personalInfo = data;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(WorkHistory data)
    {
        workHistory = data;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> data)
    {
        references = data;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string data)
    {
        coverLetter = data;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        if (personalInfo is null || workHistory is null || references is null || coverLetter is null)
            return;

        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(personalInfo, workHistory, references, coverLetter);
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

